// main.js
const parser = new Worker('/workers/csv.js', { type: 'module' });

function parseCsv(buffer) {
  return new Promise((resolve, reject) => {
    const id = crypto.randomUUID();
    const onMessage = (e) => {
      if (e.data.id !== id) return;
      parser.removeEventListener('message', onMessage);
      e.data.error ? reject(new Error(e.data.error)) : resolve(e.data.rows);
    };
    parser.addEventListener('message', onMessage);

    // Transfer the ArrayBuffer: zero-copy, main thread's copy is detached
    parser.postMessage({ id, buffer }, [buffer]);
  });
}

// UI stays responsive while a 50MB CSV parses off-thread:
fileInput.addEventListener('change', async (e) => {
  const buffer = await e.target.files[0].arrayBuffer();
  setLoading(true);
  try {
    const rows = await parseCsv(buffer);
    renderTable(rows.slice(0, 500));          // virtualize: don't render 1M rows!
  } finally {
    setLoading(false);
  }
});

